import java.io.*;
import java.util.*;

public class B {
    public static void main(String[] args) throws IOException {
        DataInputStream dis = new DataInputStream(System.in);
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        String line = br.readLine();
        int n = Integer.parseInt(line.trim());
        String s = br.readLine().trim();
        br.close();

        int maxSegment = 0;
        int underCount = 0;
        int lastBoundary = -1;
        boolean inside = false;

        for (int index = 0; index < s.length(); index++) {
            char c = s.charAt(index);
            if (c == '_') {
                if (lastBoundary != index - 1) {
                    if (inside) {
                        underCount++;
                    } else {
                        maxSegment = Math.max(maxSegment, index - 1 - lastBoundary);
                    }
                }
                lastBoundary = index;
            } else if (c == '(') {
                inside = true;
                if (lastBoundary != index - 1) {
                    maxSegment = Math.max(maxSegment, index - 1 - lastBoundary);
                }
                lastBoundary = index;
            } else if (c == ')') {
                inside = false;
                if (lastBoundary != index - 1) {
                    underCount++;
                }
                lastBoundary = index;
            }
        }

        if (lastBoundary != s.length() - 1) {
            maxSegment = Math.max(maxSegment, s.length() - 1 - lastBoundary);
        }

        System.out.println(maxSegment + " " + underCount);
    }
}
